function questIsEligible(state:JourneyState,quest:QuestDefinition){return quest.conditions(state)&&(!quest.prerequisites||quest.prerequisites.every(id=>questDone(state,id)))}
function eligibleQuestDefinitions(state:JourneyState){return questDefinitions.filter(quest=>questIsEligible(state,quest)&&!questDone(state,quest.id)).sort((a,b)=>a.priority-b.priority)}
