function statusClass(status:AdminStatus){return `status-${status.replace('相談予約済み','reserved').replace('対応済み','done').replace('連絡済み','contacted').replace('要確認','review').replace('新規','new')}`}
function statusLabel(value:string){return value||'未選択'}
function dateLabel(value:string){ const d=new Date(`${value}T00:00:00`); return Number.isNaN(d.getTime())?'日付未入力':new Intl.DateTimeFormat('ja-JP',{year:'numeric',month:'long',day:'numeric'}).format(d); }
function consultationSummary(item:Consultation){return `相談者の入力では、亡くなった方との関係は「${item.relationship}」、死亡日は${dateLabel(item.deathDate)}です。遺言書は「${item.will}」、不動産は「${item.realEstate}」、預貯金・証券は「${item.assets}」、借金・ローンは「${item.debt}」と回答されています。現在困っていることは「${item.concern}」です。`}
function reviewItems(item:Consultation){return [['借金・ローン',item.debt],['遺言書',item.will],['不動産',item.realEstate],['預貯金・証券',item.assets],['他の相続人候補',item.heirs]].filter(([,value])=>value==='わからない'||value==='') as Array<[string,string]>}

function extractFacts(text:string):JourneyFact[]{
  const facts:JourneyFact[]=[]; const add=(id:string, fact:string, status:FactStatus)=>facts.push({id,text:fact,status,source:'入力文'});
  if(/父|母|お父|お母/.test(text)&&/亡くな|他界|死去/.test(text)) add('relationship','入力文に「父・母」と亡くなったことの記述がありました','confirmed');
  if(/不動産|実家|家|土地|マンション/.test(text)) add('realEstate','不動産がある可能性についての記述がありました','checking');
  if(/銀行|口座|預金|証券|通帳/.test(text)) add('assets','預貯金・証券に関する記述がありました','confirmed');
  if(/借金|ローン|保証|債務/.test(text)) add('debt','借金・ローン・保証債務に関する記述がありました','checking');
  if(/遺言/.test(text)) add('will','遺言書に関する記述がありました','checking');
  if(/兄弟|きょうだい|相続人|子ども|子供/.test(text)) add('heirs','相続人候補に関する記述がありました','checking');
  if(!facts.length) add('none','入力文から事実を自動確定できる項目はまだありません','unconfirmed');
  return facts;
}
function factStatusLabel(status:FactStatus){return status==='confirmed'?'確認できたこと':status==='checking'?'確認中':'まだ分からないこと'}
function factStatusClass(status:FactStatus){return `fact-${status}`}
function priorityRank(priority:Priority){return priority==='high'?0:priority==='normal'?1:2}
function calculateProgress(state:JourneyState){const important=['deathDate','municipality','relationship','will','realEstate','assets','debt'];const confirmed=new Set(state.facts.filter(f=>f.status==='confirmed').map(f=>f.id));const importantCount=important.filter(id=>confirmed.has(id)||Boolean(state.answers[id as keyof Answers])).length;const answered=Object.keys(state.checkAnswers).length;const done=Object.values(state.questStates).filter(v=>v==='done').length;const chapters=new Set(questDefinitions.filter(quest=>state.questStates[quest.id]==='done').map(quest=>quest.chapter)).size;const discoveries=Object.values(state.programs).filter(v=>v==='done').length;return Math.min(92,state.started?Math.max(25,20+importantCount*4+answered*3+done*2+chapters*3+discoveries*2):0)}
function actionLabel(answer:CheckAnswer){return answer.label.replace('分からない','分からないまま')}

export default function Home(){
  const [screen,setScreen]=useState<Screen>('home'); const [journey,setJourney]=useState<JourneyState>(initialJourney); const [hydrated,setHydrated]=useState(false); const [selectedQuestId,setSelectedQuestId]=useState<QuestId|null>(null); const [journeyNotice,setJourneyNotice]=useState(''); const [todayFact,setTodayFact]=useState('');
  const [consultations,setConsultations]=useState<Consultation[]>(demoConsultations); const [adminFilter,setAdminFilter]=useState<'すべて'|AdminStatus>('すべて'); const [adminAssetFilter,setAdminAssetFilter]=useState<'すべて'|'借金あり／不明'|'不動産あり'>('すべて'); const [adminSearch,setAdminSearch]=useState(''); const [selectedConsultationId,setSelectedConsultationId]=useState<number|null>(null);
  // Hydration is kept explicit so a saved local journey can reopen without touching the server.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(()=>{try{const raw=window.localStorage.getItem(storageKey);if(raw){const saved=JSON.parse(raw) as Partial<JourneyState>;setJourney({...initialJourney,...saved,checkAnswers:{...initialJourney.checkAnswers,...(saved.checkAnswers||{})},skippedChecks:saved.skippedChecks||[],questStates:{...initialJourney.questStates,...(saved.questStates||{})},programs:{...initialJourney.programs,...(saved.programs||{})}})}}catch{/* localStorage is optional */}setHydrated(true)},[]);
  useEffect(()=>{if(hydrated)window.localStorage.setItem(storageKey,JSON.stringify(journey))},[journey,hydrated]);
  const go=(next:Screen)=>{setScreen(next);setJourneyNotice('');window.scrollTo({top:0,behavior:'smooth'})}; const openAdmin=()=>{setSelectedConsultationId(null);go('admin')}; const openConsultation=(id:number)=>{setSelectedConsultationId(id);go('admin-detail')}; const updateConsultation=(id:number,changes:Partial<Consultation>)=>setConsultations(items=>items.map(item=>item.id===id?{...item,...changes}:item)); const updateJourney=(changes:Partial<JourneyState>)=>setJourney(prev=>({...prev,...changes}));
  const startFreeInput=(e:FormEvent)=>{e.preventDefault();if(!journey.freeText.trim()){setJourneyNotice('まずは書ける範囲で、状況を入力してください。');return}updateJourney({started:true,facts:extractFacts(journey.freeText)});go('understood')}; const startQuestions=()=>{updateJourney({started:true});go('question')};
  const eligibleChecks=useMemo(()=>checkDefinitions.filter(def=>def.conditions(journey)).sort((a,b)=>priorityRank(a.priority)-priorityRank(b.priority)),[journey]);
  const nextCheck=eligibleChecks[0]??null;
  const deferredChecks=checkDefinitions.filter(def=>journey.skippedChecks.includes(def.id)&&!journey.checkAnswers[def.id]);
  const eligibleQuests=useMemo(()=>eligibleQuestDefinitions(journey),[journey]);
  const mainQuest=eligibleQuests.find(quest=>quest.type==='main')??null;
  const nextQuest=mainQuest??eligibleQuests[0]??null;
  const sideQuests=eligibleQuests.filter(quest=>quest.id!==nextQuest?.id&&quest.type==='side').slice(0,2);
  const completedQuests=questDefinitions.filter(quest=>questDone(journey,quest.id));
  const activeDiscoveries=discoveryDefinitions.filter(def=>def.conditions(journey));
  const progress=useMemo(()=>calculateProgress(journey),[journey]); const confirmedFacts=journey.facts.filter(f=>f.status==='confirmed'); const checkingFacts=journey.facts.filter(f=>f.status==='checking'); const unknownFacts=journey.facts.filter(f=>f.status==='unconfirmed'); const selectedQuest=questDefinitions.find(q=>q.id===selectedQuestId)??null;
  const confirmFact=(id:string,status:FactStatus)=>updateJourney({facts:journey.facts.map(f=>f.id===id?{...f,status}:f)});
  const answerCheck=(definition:CheckDefinition,answerValue:string,rawValue?:string)=>{const answer=definition.answers.find(item=>item.value===answerValue)??definition.answers[0];const label=rawValue||answer.label;const normalizedValue=rawValue?(rawValue?'known':'unknown'):answer.value;const nextAnswers={...journey.answers,...(definition.factId==='deathDate'?{deathDate:rawValue||''}:{}),...(definition.factId==='municipality'?{municipality:rawValue||''}:{}),...(definition.factId==='relationship'?{relationship:answer.label}:{})};const status=normalizedValue==='unknown'||normalizedValue==='not-searched'?'checking':'confirmed';const nextFacts=[...journey.facts.filter(f=>f.id!==definition.factId),{id:definition.factId,text:`${definition.title}：「${label}」`,status,source:'質問' as const}];const nextQuestStates={...journey.questStates,...(answer.questId?{[answer.questId]:journey.questStates[answer.questId]==='done'?'done':'todo'}:{})};const nextJourney:JourneyState={...journey,answers:nextAnswers,checkAnswers:{...journey.checkAnswers,[definition.id]:normalizedValue},facts:nextFacts,questStates:nextQuestStates,lastFeedback:{kind:'check',title:'ひとつ整理できました',subject:definition.title,message:answer.feedback,changes:[`${definition.title}を「${label}」として記録しました。`,...(answer.questId?[`次の確認候補「${questDefinitions.find(q=>q.id===answer.questId)?.title}」を追加しました。`]:[])],discoveries:answer.discoveryIds||[],beforeProgress:progress,afterProgress:calculateProgress({...journey,answers:nextAnswers,checkAnswers:{...journey.checkAnswers,[definition.id]:normalizedValue},facts:nextFacts,questStates:nextQuestStates})}};setJourney(nextJourney);go('feedback')};
  const deferCheck=(definition:CheckDefinition)=>{const nextJourney:JourneyState={...journey,skippedChecks:[...journey.skippedChecks,definition.id],lastFeedback:{kind:'check',title:'確認候補を後で見ることにしました',subject:definition.title,message:'今すぐ決めなくても大丈夫です。現在地に残して、後で見返せます。',changes:[`「${definition.title}」を後で確認する項目として保存しました。`],discoveries:[],beforeProgress:progress,afterProgress:progress}};setJourney(nextJourney);go('feedback')};
  const continueFromFeedback=()=>{updateJourney({lastFeedback:undefined});go(nextQuest?'current':nextCheck?'question':'current')};
  const pauseToday=()=>{const feedback=journey.lastFeedback;updateJourney({lastFeedback:undefined,lastPause:{completed:feedback?.kind==='quest'?[feedback.subject]:[],discoveries:feedback?.discoveries||[]}});go('pause')};
  const openQuest=(id:QuestId)=>{setSelectedQuestId(id);go('quest')};
  const openQuestLog=()=>go('quest-log');
  const toggleChecklist=(key:string)=>updateJourney({checklist:{...journey.checklist,[key]:!journey.checklist[key]}});
  const setQuestResult=(id:QuestId,value:string)=>updateJourney({questResults:{...journey.questResults,[id]:value}});
  const completeQuest=()=>{if(!selectedQuestId||!selectedQuest)return;const nextStates={...journey.questStates,[selectedQuestId]:'done' as const};const nextJourneyState={...journey,questStates:nextStates};const beforeIds=new Set(eligibleQuests.map(quest=>quest.id));const newlyUnlocked=eligibleQuestDefinitions(nextJourneyState).filter(quest=>!beforeIds.has(quest.id));const discoveries=(selectedQuest.relatedDiscoveries||[]).filter(id=>activeDiscoveries.some(discovery=>discovery.id===id));const nextJourney:JourneyState={...nextJourneyState,lastFeedback:{kind:'quest',title:'今日ひとつ進みました',subject:selectedQuest.title,message:'確認した内容を、現在地に反映しました。',changes:[`「${selectedQuest.title}」を完了として記録しました。`,...(newlyUnlocked.length?newlyUnlocked.slice(0,2).map(quest=>`新しい確認事項が見つかりました：「${quest.title}」`):[])],discoveries,beforeProgress:progress,afterProgress:calculateProgress(nextJourneyState)}};setJourney(nextJourney);go('feedback')};
  const laterQuest=()=>{if(!selectedQuestId)return;updateJourney({questStates:{...journey.questStates,[selectedQuestId]:'later'}});setJourneyNotice('この確認は後で見返せるように残しました。');go('current')};
  const addTodayFact=(e:FormEvent)=>{e.preventDefault();const text=todayFact.trim();if(!text)return;const kind=/分からない|まだ|不明|確認中|未確認/.test(text)?'pending':'new';const id=Date.now();updateJourney({addedFacts:[...journey.addedFacts,{id,text,kind}],facts:[...journey.facts,{id:`note-${id}`,text:`今日のメモ：${text}`,status:kind==='pending'?'checking':'confirmed',source:'追加情報'}]});setTodayFact('');setJourneyNotice(kind==='pending'?'「確認が必要なこと」として追加しました。':'新しく分かったこととして追加しました。')};
  const resetJourney=()=>{window.localStorage.removeItem(storageKey);setJourney(initialJourney);setTodayFact('');setJourneyNotice('');go('home')}; const saveProgram=(id:DiscoveryId,value:'saved'|'done')=>updateJourney({programs:{...journey.programs,[id]:value}});
  const visibleConsultations=useMemo(()=>consultations.filter(item=>{const matchesFilter=adminFilter==='すべて'||item.status===adminFilter;const matchesAsset=adminAssetFilter==='すべて'||(adminAssetFilter==='不動産あり'&&item.realEstate==='ある')||(adminAssetFilter==='借金あり／不明'&&(item.debt==='ある'||item.debt==='わからない'));const q=adminSearch.trim().toLowerCase();const matchesSearch=!q||`${item.name} ${item.municipality}`.toLowerCase().includes(q);return matchesFilter&&matchesAsset&&matchesSearch}),[consultations,adminFilter,adminAssetFilter,adminSearch]); const selectedConsultation=consultations.find(item=>item.id===selectedConsultationId)??null; const adminCounts=useMemo(()=>({new:consultations.filter(item=>item.status==='新規').length,review:consultations.filter(item=>item.status==='要確認').length,reserved:consultations.filter(item=>item.status==='相談予約済み').length,done:consultations.filter(item=>item.status==='対応済み').length}),[consultations]);

  return <div className="app-shell">
    <header className="site-header"><button className="brand" onClick={()=>go('home')}><span className="brand-mark">結</span><span><b>おやすみ手続きナビ</b><small>相続の初期整理を、ひとつずつ。</small></span></button><div className="header-actions">{screen==='admin'||screen==='admin-detail'?<button className="admin-demo-link" onClick={()=>go('home')}>一般画面へ戻る</button>:<button className="admin-demo-link" onClick={openAdmin}>事業者向けデモ</button>}<span className="header-note">無料・登録不要</span></div></header>

    {screen==='admin'&&<main className="admin-screen"><div className="admin-heading"><div><p className="eyebrow">事業者向け管理画面</p><h1>おやすみ手続きナビ｜事業者向け</h1><p>デモ管理画面 · 相談前に状況を整理することで、初回ヒアリングの時間を短縮し、確認漏れを減らします。</p></div><span className="admin-demo-badge">DEMO</span></div><div className="admin-summary-grid"><article><span>新規相談</span><b>{adminCounts.new}</b><small>入力直後の相談</small></article><article className="is-review"><span>要確認</span><b>{adminCounts.review}</b><small>追加確認が必要な項目あり</small></article><article><span>相談予約済み</span><b>{adminCounts.reserved}</b><small>次回相談につながった相談</small></article><article><span>対応済み</span><b>{adminCounts.done}</b><small>対応メモを残した相談</small></article></div><section className="admin-panel"><div className="admin-panel-heading"><div><p className="eyebrow">相談者一覧</p><h2>事前ヒアリング</h2></div><span>{visibleConsultations.length}件表示</span></div><div className="admin-toolbar"><label className="admin-search"><span>検索</span><input type="search" placeholder="相談者名・市区町村で検索" value={adminSearch} onChange={e=>setAdminSearch(e.target.value)}/></label><label><span>ステータス</span><select value={adminFilter} onChange={e=>setAdminFilter(e.target.value as 'すべて'|AdminStatus)}><option>すべて</option>{statusOptions.map(status=><option key={status}>{status}</option>)}</select></label><label><span>確認条件</span><select value={adminAssetFilter} onChange={e=>setAdminAssetFilter(e.target.value as 'すべて'|'借金あり／不明'|'不動産あり')}><option>すべて</option><option>借金あり／不明</option><option>不動産あり</option></select></label></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>相談者</th><th>入力日時</th><th>関係</th><th>死亡日</th><th>不動産</th><th>借金</th><th>遺言</th><th>ステータス</th><th></th></tr></thead><tbody>{visibleConsultations.map(item=><tr key={item.id}><td><b>{item.name}</b><small>{item.municipality}</small></td><td>{item.inputAt}</td><td>{item.relationship}</td><td>{dateLabel(item.deathDate)}</td><td><span className={`value-chip ${item.realEstate==='ある'?'is-yes':''}`}>{statusLabel(item.realEstate)}</span></td><td><span className={`value-chip ${item.debt==='わからない'?'is-unknown':item.debt==='ある'?'is-yes':''}`}>{statusLabel(item.debt)}</span></td><td><span className={`value-chip ${item.will==='わからない'?'is-unknown':''}`}>{statusLabel(item.will)}</span></td><td><select className={`status-select ${statusClass(item.status)}`} value={item.status} onChange={e=>updateConsultation(item.id,{status:e.target.value as AdminStatus})}>{statusOptions.map(status=><option key={status}>{status}</option>)}</select></td><td><button className="detail-button" onClick={()=>openConsultation(item.id)}>詳細を見る →</button></td></tr>)}</tbody></table>{visibleConsultations.length===0&&<p className="empty-state">条件に一致する相談者はいません。</p>}</div></section></main>}

    {screen==='admin-detail'&&selectedConsultation&&<main className="admin-screen"><div className="admin-detail-top"><button className="back-admin" onClick={()=>go('admin')}>← 相談者一覧へ戻る</button><span className="admin-demo-badge">デモ管理画面</span></div><section className="detail-heading"><div><p className="eyebrow">相談者詳細</p><h1>{selectedConsultation.name}</h1><p>入力日時：{selectedConsultation.inputAt}</p></div><label className={`detail-status ${statusClass(selectedConsultation.status)}`}><span>対応ステータス</span><select value={selectedConsultation.status} onChange={e=>updateConsultation(selectedConsultation.id,{status:e.target.value as AdminStatus})}>{statusOptions.map(status=><option key={status}>{status}</option>)}</select></label></section><section className="admin-detail-grid"><article className="admin-detail-card"><h2>基本情報</h2><dl><div><dt>入力日時</dt><dd>{selectedConsultation.inputAt}</dd></div><div><dt>相談者名</dt><dd>{selectedConsultation.name}</dd></div><div><dt>連絡先</dt><dd>{selectedConsultation.contact}</dd></div><div><dt>亡くなった方との関係</dt><dd>{selectedConsultation.relationship}</dd></div><div><dt>死亡日</dt><dd>{dateLabel(selectedConsultation.deathDate)}</dd></div><div><dt>最後の住所</dt><dd>{selectedConsultation.municipality}</dd></div></dl></article><article className="admin-detail-card"><h2>相続状況</h2><dl><div><dt>遺言書</dt><dd>{selectedConsultation.will}</dd></div><div><dt>不動産</dt><dd>{selectedConsultation.realEstate}</dd></div><div><dt>預貯金・証券</dt><dd>{selectedConsultation.assets}</dd></div><div><dt>借金・ローン</dt><dd>{selectedConsultation.debt}</dd></div><div><dt>他の相続人候補</dt><dd>{selectedConsultation.heirs}</dd></div><div><dt>亡くなった年の収入</dt><dd>{selectedConsultation.income}</dd></div></dl></article></section><section className="admin-detail-card concern-card"><h2>現在困っていること</h2><p>{selectedConsultation.concern}</p><small>相談者の自由入力をそのまま表示しています。法的な自動分析には使いません。</small></section><section className="admin-detail-card"><div className="section-heading-row"><div><h2>事前ヒアリング要約</h2><small>入力情報の要約</small></div></div><p className="summary-copy">{consultationSummary(selectedConsultation)}</p></section><section className="admin-detail-card"><h2>確認ポイント</h2><p className="admin-card-note">入力データ上、追加確認した方がよい未確認項目です。法的な評価や結論ではありません。</p>{reviewItems(selectedConsultation).length?<ul className="review-list">{reviewItems(selectedConsultation).map(([label,value])=><li key={label}><span>{label}</span><b>{value||'未入力'}</b></li>)}</ul>:<p className="no-review">未確認として登録されている項目はありません。</p>}</section><section className="admin-detail-card note-card"><div className="section-heading-row"><div><h2>次回相談用メモ</h2><small>電話・面談・資料依頼など</small></div><span>この端末上のデモ状態のみ</span></div><textarea rows={5} placeholder="電話で確認すること、面談で聞くこと、持参を依頼する資料など" value={selectedConsultation.note} onChange={e=>updateConsultation(selectedConsultation.id,{note:e.target.value})}/><p>このメモはブラウザ内のReact stateで扱うデモ用です。サーバーへ保存・送信されません。</p></section></main>}

    {screen==='home'&&<main className="journey-shell"><section className="journey-hero"><div><p className="eyebrow">大切な方を亡くされた直後のために</p><h1>相続、<br/><em>何から手をつければいい？</em></h1><p className="journey-lead">今わかっていることから整理して、次に確認することをひとつずつ見つけます。</p><p className="journey-reassure">全部を一度に理解する必要はありません。</p>{journey.started?<div className="resume-card"><span>前回の続きから</span><b>情報整理：{progress}%</b><small>{nextQuest?`次は「${nextQuest.title}」を確認します。`:nextCheck?`次は「${nextCheck.title}」を確認します。`:'確認内容を見返せます。'}</small><button className="primary" onClick={()=>go('current')}>続きから見る <span>→</span></button><button className="text-button" onClick={resetJourney}>最初からやり直す</button></div>:<><button className="primary" onClick={()=>go('free-input')}>整理をはじめる <span>→</span></button><p className="privacy">✓ 入力内容はこの端末のブラウザにのみ保存できます　　登録不要</p></>}</div><div className="journey-map"><p>進め方</p><div><span>1</span><b>書ける範囲で伝える</b><small>自由入力か質問から選べます</small></div><i/><div><span>2</span><b>ここまで分かったことを確認</b><small>推測はせず、修正できます</small></div><i/><div><span>3</span><b>次の確認をひとつ選ぶ</b><small>あとでやることもできます</small></div></div></section><section className="journey-trust"><div><b>法律判断はしません</b><p>一般的な確認事項を整理するデモです。</p></div><div><b>分からないままで大丈夫</b><p>確認中の項目として残せます。</p></div><div><b>端末内だけに保存</b><p>サーバーやDBへ送信しません。</p></div></section></main>}

    {screen==='free-input'&&<main className="journey-page"><JourneyProgress label="最初の入力" step="1 / 3"/><section className="journey-panel intro-panel"><p className="eyebrow">書ける範囲で大丈夫です</p><h1>いまの状況を、言葉にしてみる</h1><p>まとまっていなくても大丈夫です。入力した文章は、事実を自動で確定するためではなく、確認のきっかけを見つけるために使います。</p><form onSubmit={startFreeInput}><textarea className="journey-input" rows={8} placeholder="例：父が亡くなりました。実家と銀行口座がありそうですが、借金があるかは分かりません。何から始めればいいか知りたいです。" value={journey.freeText} onChange={e=>updateJourney({freeText:e.target.value})}/><small>書ける範囲で大丈夫です。固有名詞や個人情報は入力しないでください。</small>{journeyNotice&&<p className="journey-error" role="alert">{journeyNotice}</p>}<div className="actions"><button type="button" className="text-button" onClick={()=>go('home')}>← 戻る</button><button className="primary">ここまで整理する <span>→</span></button></div></form></section><section className="alternate-card"><b>文章より質問の方が答えやすい方へ</b><p>死亡日や市区町村などを、ひとつずつ確認できます。</p><button className="outline" onClick={startQuestions}>質問に答えて整理する</button></section></main>}

    {screen==='understood'&&<main className="journey-page"><JourneyProgress label="ここまで分かりました" step="2 / 3"/><section className="journey-panel"><p className="eyebrow">入力文から見つかった手がかり</p><h1>ここまで分かりました</h1><p>文章から読み取れたキーワードを、確定せずに表示しています。合っていないものは「要修正」にしてください。</p><blockquote className="input-quote">{journey.freeText}</blockquote><div className="fact-list">{journey.facts.map(fact=><article key={fact.id} className={`fact-card ${factStatusClass(fact.status)}`}><div><span className="fact-badge">{factStatusLabel(fact.status)}</span><p>{fact.text}</p></div>{fact.id!=='none'&&<div className="fact-actions"><button onClick={()=>confirmFact(fact.id,'confirmed')}>この理解で合っています</button><button onClick={()=>confirmFact(fact.id,'checking')}>要修正・確認中</button></div>}</article>)}</div><p className="quiet-note">自動推測で法律上の結論を出すことはありません。追加の質問で、分かる範囲を補えます。</p><div className="actions"><button className="text-button" onClick={()=>go('free-input')}>← 入力を修正</button><div><button className="outline" onClick={()=>go('current')}>いったん現在地を見る</button><button className="primary inline-primary" onClick={startQuestions}>不足情報を確認する <span>→</span></button></div></div></section></main>}

    {screen==='question'&&nextCheck&&<main className="journey-page"><JourneyProgress label="次に整理するポイント" step="いま確認すること"/><section className="journey-panel discovery-question"><p className="eyebrow">次に整理するポイント</p><h1>{nextCheck.title}</h1><div className="context-grid"><article><span>今わかっていること</span><p>{journey.facts.filter(f=>f.status==='confirmed').slice(-4).map(f=>f.text).join('、')||'まだ入力されていません。'}</p></article><article><span>まだわかっていないこと</span><p>{journey.facts.filter(f=>f.status!=='confirmed').slice(-4).map(f=>f.text).join('、')||'この項目についての情報がまだありません。'}</p></article></div><section className="why-now"><b>なぜ今これを確認する？</b><p>{nextCheck.reason(journey)}</p><b>それが分かると何の整理につながる？</b><p>{nextCheck.consequence}</p></section><h2 className="question-prompt">{nextCheck.question}</h2>{nextCheck.inputType?<form onSubmit={e=>{e.preventDefault();const value=(e.currentTarget.elements.namedItem(nextCheck.id) as HTMLInputElement).value.trim();if(value)answerCheck(nextCheck,'known',value)}}><input name={nextCheck.id} type={nextCheck.inputType} className="journey-text-input" placeholder={nextCheck.id==='municipality'?'例：世田谷区、横浜市':undefined}/><button className="primary">記録する <span>→</span></button></form>:<div className="answer-options">{nextCheck.answers.map(answer=><button key={answer.value} onClick={()=>answerCheck(nextCheck,answer.value)}>{actionLabel(answer)}<span>→</span></button>)}</div>}<button className="text-button question-later" onClick={()=>deferCheck(nextCheck)}>あとで確認する</button><button className="text-button question-later" onClick={()=>go('current')}>いったん現在地を見る</button></section></main>}

    {screen==='feedback'&&journey.lastFeedback&&<main className="journey-page"><section className="feedback-panel"><p className="eyebrow">状況の地図が更新されました</p><h1>{journey.lastFeedback.title}</h1><div className="feedback-subject">✓ {journey.lastFeedback.subject}</div><p className="feedback-message">{journey.lastFeedback.message}</p><ul className="feedback-changes">{journey.lastFeedback.changes.map(change=><li key={change}>{change}</li>)}</ul>{journey.lastFeedback.discoveries.length>0&&<section className="discovery-alert"><b>新しい確認候補が見つかりました</b>{journey.lastFeedback.discoveries.map(id=>{const discovery=discoveryDefinitions.find(item=>item.id===id);return discovery?<p key={id}>{discovery.title}</p>:null})}</section>}<div className="feedback-progress"><span>情報整理</span><b>{journey.lastFeedback.beforeProgress}% → {journey.lastFeedback.afterProgress}%</b><small>このサービス上の情報整理状況です。法的な手続きの完了率ではありません。</small></div><div className="actions"><button className="outline" onClick={pauseToday}>今日はここまで</button><button className="primary" onClick={continueFromFeedback}>次に整理する <span>→</span></button></div></section></main>}

    {screen==='pause'&&<main className="journey-page"><section className="pause-panel"><p className="eyebrow">保存しました</p><h1>今日はここまででも大丈夫です</h1><p>確認した内容と進捗は、この端末のブラウザに保存されています。次回は「前回の続きから」再開できます。</p><div className="pause-summary"><h2>今日進んだこと</h2>{journey.lastPause?.completed.map(item=><p key={item}>✓ {item}</p>)}{journey.lastPause?.completed.length===0&&confirmedFacts.slice(-5).map(f=><p key={f.id}>✓ {f.text}</p>)}{(!journey.lastPause||journey.lastPause.completed.length===0)&&confirmedFacts.length===0&&<p>まだ確定した項目はありません。</p>}</div><div className="pause-summary"><h2>新しい確認候補</h2>{journey.lastPause?.discoveries.map(id=><p key={id}>＋ {discoveryDefinitions.find(item=>item.id===id)?.title}</p>)}{(!journey.lastPause||journey.lastPause.discoveries.length===0)&&<p>今回の新しい候補はありません。</p>}</div><div className="pause-summary"><h2>次回のメインクエスト</h2><p>△ {nextQuest?.title||nextCheck?.title||'現在地の整理を見返す'}</p></div><div className="actions"><button className="outline" onClick={()=>go('home')}>ホームへ戻る</button><button className="primary" onClick={()=>go(nextQuest?'current':nextCheck?'question':'current')}>続ける <span>→</span></button></div></section></main>}

    {false&&<main className="journey-page current-page"><section className="current-hero"><div><p className="eyebrow">いまの整理状況</p><h1>あなたの現在地</h1><p>ここで表示するのは、入力・確認項目の整理状況です。法的な手続きの完了度ではありません。</p></div><div className="progress-orb"><strong>{progress}%</strong><small>情報整理</small></div></section><section className="progress-panel"><div className="progress-label"><b>情報整理：{progress}%</b><span>分かっていることを少しずつ</span></div><div className="progress-bar"><i style={{width:`${progress}%`}}/></div></section><section className="status-groups"><FactGroup title="確認できたこと" tone="confirmed" facts={confirmedFacts}/><FactGroup title="確認中" tone="checking" facts={checkingFacts}/><FactGroup title="まだ分からないこと" tone="unconfirmed" facts={unknownFacts}/></section><section className="causal-flow"><div><span>分かっていること</span><b>{confirmedFacts.slice(-3).map(f=>f.text).join('、')||'これから整理します'}</b></div><i>↓</i><div><span>まだ分からないこと</span><b>{checkingFacts.concat(unknownFacts).slice(-3).map(f=>f.text).join('、')||'今のところありません'}</b></div><i>↓</i><div><span>このため、次に</span><b>{nextQuest?.title||nextCheck?.title||'現在地を見返す'}</b></div><i>↓</i><div><span>その先に確認候補</span><b>{activeDiscoveries.map(d=>d.title).join('、')||'情報が増えると候補が表示されます'}</b></div></section>{journey.addedFacts.length>0&&<section className="added-facts"><h2>今日追加したメモ</h2>{journey.addedFacts.map(f=><p key={f.id}><span>{f.kind==='new'?'新しく分かったこと':'確認が必要なこと'}</span>{f.text}</p>)}</section>}{journeyNotice&&<p className="journey-notice" role="status">{journeyNotice}</p>}<section className="next-quest"><div className="section-kicker">次に整理すること</div>{nextQuest?<><h2>{nextQuest.title}</h2><p>{nextQuest.reason(journey)}</p><div className="quest-state-row"><span className={`quest-state state-${journey.questStates[nextQuest.id]}`}>{journey.questStates[nextQuest.id]==='later'?'後で確認':'確認候補'}</span><button className="primary" onClick={()=>openQuest(nextQuest.id)}>確認をはじめる <span>→</span></button></div></>:nextCheck?<><h2>{nextCheck.title}</h2><p>{nextCheck.reason(journey)}</p><div className="quest-state-row"><span className="quest-state state-todo">今確認しておきたい</span><button className="primary" onClick={()=>go('question')}>確認ポイントを見る <span>→</span></button></div></>:<p>今表示されている確認項目を、必要なときに見返してください。</p>}</section>{deferredChecks.length>0&&<section className="deferred-card"><h2>後で確認すること</h2>{deferredChecks.map(def=><button key={def.id} onClick={()=>{updateJourney({skippedChecks:journey.skippedChecks.filter(id=>id!==def.id)});go('question')}}>{def.title}<span>→</span></button>)}</section>}<section className="today-panel"><div><p className="section-kicker">小さな更新</p><h2>今日、何か分かったことはありますか？</h2><p>新しく分かったことと、まだ確認が必要なことを区別して残します。</p></div><form onSubmit={addTodayFact}><textarea rows={3} placeholder="例：通帳が2冊見つかった／借金はまだ分からない" value={todayFact} onChange={e=>setTodayFact(e.target.value)}/><button className="outline">整理状況に追加</button></form></section>{activeDiscoveries.map(discovery=><ProgramCard key={discovery.id} discovery={discovery} status={journey.programs[discovery.id]} onSave={saveProgram}/>)}<Timeline/><section className="local-note"><b>この端末のブラウザにのみ保存されます</b><p>ログイン・サーバー保存・外部送信はありません。共有端末では使い終わったら初期化してください。</p><button className="reset-button" onClick={()=>go('pause')}>今日はここまで</button><button className="reset-button" onClick={resetJourney}>このデモの入力・進捗を初期化</button></section></main>}

    {screen==='current'&&<main className="journey-page current-home-page"><section className="home-status-strip"><div><p className="eyebrow">mimi上の情報整理マップ</p><h1>あなたの現在地</h1><p>今の一歩に必要な情報だけを、見やすくまとめています。</p></div><div className="progress-orb"><strong>{progress}%</strong><small>情報整理</small></div></section><section className="home-progress"><div className="progress-label"><b>情報整理：{progress}%</b><span>相続手続きの完了率ではありません</span></div><div className="progress-bar"><i style={{width:`${progress}%`}}/></div></section><section className="main-quest-card">{nextQuest?<><div className="home-card-kicker">今やること · メインクエスト</div><h2>{nextQuest.title}</h2><p>{nextQuest.reason(journey)}</p><div className="quest-state-row"><span className="quest-priority">まずこれ</span><button className="primary" onClick={()=>openQuest(nextQuest.id)}>確認を始める <span>→</span></button></div></>:nextCheck?<><div className="home-card-kicker">今やること · 確認ポイント</div><h2>{nextCheck.title}</h2><p>{nextCheck.reason(journey)}</p><button className="primary" onClick={()=>go('question')}>確認を始める <span>→</span></button></>:<><div className="home-card-kicker">今日の現在地</div><h2>今はここまで整理できています</h2><p>必要なときに、記録や発見を見返せます。</p></>}</section>{sideQuests.length>0&&<section className="side-quest-section"><div className="section-heading-row"><div><p className="home-card-kicker">今すぐでなくても進められること</p><h2>サブクエスト</h2></div><span>最大2件</span></div><div className="side-quest-list">{sideQuests.map(quest=><QuestSummary key={quest.id} quest={quest} state={journey} onOpen={openQuest}/>)}</div></section>}<section className="home-shortcuts"><button onClick={openQuestLog}><span>✓</span><b>完了したことを見る</b><small>{completedQuests.length}件のクエスト</small><strong>→</strong></button><button onClick={()=>document.getElementById('home-discovery')?.scrollIntoView({behavior:'smooth'})}><span>＋</span><b>発見した制度を見る</b><small>{activeDiscoveries.length}件の確認候補</small><strong>→</strong></button></section><section className="today-panel home-today"><div><p className="section-kicker">小さな更新</p><h2>今日、何か分かったことはありますか？</h2><p>新しく分かったことと、まだ確認が必要なことを区別して残します。</p></div><form onSubmit={addTodayFact}><textarea rows={3} placeholder="例：通帳が2冊見つかった／借金はまだ分からない" value={todayFact} onChange={e=>setTodayFact(e.target.value)}/><button className="outline">記録する</button></form></section><section id="home-discovery" className="home-discovery-section"><div className="section-heading-row"><div><p className="home-card-kicker">条件が整うと表示されます</p><h2>新しい発見</h2></div><span>{activeDiscoveries.length}件</span></div>{activeDiscoveries.length>0?<DiscoverySummary discovery={activeDiscoveries[0]} status={journey.programs[activeDiscoveries[0].id]} onSave={saveProgram} state={journey}/>:<p className="empty-home-note">確認を進めると、関連する公的情報の候補がここに表示されます。</p>}</section><details className="home-collapsible"><summary>mimi上の情報整理マップを開く</summary><ChapterMap currentChapter={mainQuest?.chapter||1}/></details><details className="home-collapsible"><summary>確認できた情報・今日の記録を開く</summary><div className="record-grid"><FactGroup title="確認できたこと" tone="confirmed" facts={confirmedFacts}/><FactGroup title="確認中" tone="checking" facts={checkingFacts}/><FactGroup title="まだ分からないこと" tone="unconfirmed" facts={unknownFacts}/></div>{journey.addedFacts.length>0&&<div className="added-facts compact-added"><h2>今日追加したメモ</h2>{journey.addedFacts.slice(-5).map(f=><p key={f.id}><span>{f.kind==='new'?'新しく分かったこと':'確認が必要なこと'}</span>{f.text}</p>)}</div>}</details><details className="home-collapsible"><summary>一般的な手続きの目安を開く</summary><Timeline/></details>{journeyNotice&&<p className="journey-notice" role="status">{journeyNotice}</p>}<section className="local-note home-local-note"><b>この端末のブラウザにのみ保存されます</b><p>ログイン・サーバー保存・外部送信はありません。共有端末では使い終わったら初期化してください。</p><button className="reset-button" onClick={()=>go('pause')}>今日はここまで</button><button className="reset-button" onClick={resetJourney}>このデモの入力・進捗を初期化</button></section></main>}

    {screen==='quest-log'&&<main className="journey-page quest-log-page"><div className="admin-detail-top"><button className="back-admin" onClick={()=>go('current')}>← 現在地へ戻る</button><span className="admin-demo-badge">mimi上の記録</span></div><section className="quest-log-heading"><p className="eyebrow">完了したこと</p><h1>小さな達成の記録</h1><p>ここに表示するのは、mimi上で確認した行動の記録です。法的な手続きの完了を示すものではありません。</p></section><section className="completed-quest-list">{completedQuests.length>0?completedQuests.map(quest=><QuestSummary key={quest.id} quest={quest} state={journey} onOpen={openQuest} completed/>):<p className="empty-home-note">完了したクエストはまだありません。</p>}</section></main>}

    {screen==='quest'&&selectedQuest&&<main className="journey-page"><JourneyProgress label="次に整理すること" step={`第${selectedQuest.chapter}章 · ${selectedQuest.type==='main'?'メイン':'サブ'}`}/><section className="quest-detail"><p className="eyebrow">確認クエスト</p><h1>{selectedQuest.title}</h1><p className="quest-reason-label">このクエストが表示された理由</p><p className="quest-description">{selectedQuest.reason(journey)}</p><p className="quest-description">{selectedQuest.description}</p><div className="quest-mini-progress"><span>このクエストの進捗</span><b>{checklistProgress(selectedQuest,journey)}</b></div><div className="quest-checklist"><h2>確認リスト</h2>{selectedQuest.checklist.map((item,index)=>{const key=`${selectedQuest.id}:${index}`;return <label key={key}><input type="checkbox" checked={Boolean(journey.checklist[key])} onChange={()=>toggleChecklist(key)}/><span>{item}</span></label>})}</div><label className="quest-result"><span>いまの結果を選ぶ（途中でも大丈夫です）</span><select value={journey.questResults[selectedQuest.id]||''} onChange={e=>setQuestResult(selectedQuest.id,e.target.value)}><option value="">選択してください</option>{selectedQuest.results.map(result=><option key={result}>{result}</option>)}</select></label><p className="quiet-note">この画面は確認した内容を整理するためのものです。相続放棄などの要否や法律上の結論は表示しません。</p><div className="actions"><button className="text-button" onClick={()=>go('current')}>← 現在地へ戻る</button><div><button className="outline" onClick={laterQuest}>あとでやる</button><button className="primary inline-primary" onClick={completeQuest}>確認内容を更新する</button></div></div></section></main>}
    {screen==='current'&&<JourneyHud progress={progress} currentChapter={mainQuest?.chapter||1}/>}<footer><b>おやすみ手続きナビ</b><p>大切なときに、迷わないための道しるべ。</p><small>© 2026 Prototype — 入力内容はこの端末のブラウザにのみ保存されます</small></footer>
  </div>;
}

function JourneyProgress({label,step}:{label:string;step:string}){return <div className="journey-progress"><span>{step}</span><i/><b>{label}</b></div>}
function FactGroup({title,tone,facts}:{title:string;tone:FactStatus;facts:JourneyFact[]}){return <section className={`fact-group ${factStatusClass(tone)}`}><h2>{title}<span>{facts.length}</span></h2>{facts.length?<ul>{facts.map(f=><li key={f.id}>{f.text}</li>)}</ul>:<p>まだ登録されていません。</p>}</section>}
function QuestSummary({quest,state,onOpen,completed=false}:{quest:QuestDefinition;state:JourneyState;onOpen?:(id:QuestId)=>void;completed?:boolean}){const status=state.questStates[quest.id];return <article className={`quest-summary ${completed?'is-complete':''}`}><div><span className="quest-summary-meta">第{quest.chapter}章 · {quest.type==='main'?'メイン':'サブ'}{completed?' · 完了':''}</span><h3>{quest.title}</h3><p>{quest.reason(state)}</p></div>{!completed&&onOpen&&<button onClick={()=>onOpen(quest.id)}>確認を始める <span>→</span></button>}{status==='later'&&!completed&&<small className="quest-later-label">あとで確認</small>}</article>}
function DiscoverySummary({discovery,status,onSave,state}:{discovery:DiscoveryDefinition;status:'new'|'saved'|'done';onSave:(id:DiscoveryId,value:'saved'|'done')=>void;state:JourneyState}){return <article className="discovery-summary"><div><span className="quest-summary-meta">公的情報の確認候補</span><h3>{discovery.title}</h3><p>{discovery.description}</p><details><summary>なぜ今回表示された？</summary><p>{discovery.reason(state)}</p></details></div><div className="discovery-summary-actions"><OfficialLink href={discovery.href}>公式情報を見る</OfficialLink><button className={status==='saved'?'is-saved':''} onClick={()=>onSave(discovery.id,'saved')}>{status==='saved'?'追加済み':'確認リストに追加'}</button></div></article>}
function ChapterMap({currentChapter}:{currentChapter:number}){const chapters=['初動整理','遺言・負債','財産・家族関係','書類・窓口準備','各種手続き'];return <div className="chapter-map"><p>mimi上の情報整理マップです。法的な手続きの進捗ではありません。</p>{chapters.map((chapter,index)=>{const number=index+1;return <div key={chapter} className={number===currentChapter?'is-current':number<currentChapter?'is-past':''}><span>{number<currentChapter?'✓':number}</span><b>{chapter}</b><small>{number===currentChapter?'今ここ':number<currentChapter?'整理済み':'これから確認できます'}</small></div>})}</div>}
function JourneyHud({progress,currentChapter}:{progress:number;currentChapter:number}){const chapters=['初動整理','遺言・負債','財産・家族関係','書類・窓口準備','各種手続き'];const chapter=chapters[currentChapter-1]||chapters[0];return <div className="journey-hud" aria-label="mimi上の現在地"><div className="hud-brand"><b>mimi</b><span>相続ナビ</span></div><div className="hud-progress"><span>mimi上の情報整理度</span><b>{progress}%</b></div><div className="hud-location"><span>現在地</span><b>{chapter}</b><small>一般的な手続きの流れの中</small></div><div className="hud-chapters" aria-hidden="true">{chapters.map((item,index)=><span key={item} className={index+1===currentChapter?'is-current':''}>{item}</span>)}</div><details className="hud-mobile-map"><summary>章マップを開く <small>{currentChapter} / {chapters.length}</small></summary><ChapterMap currentChapter={currentChapter}/></details></div>}
function ProgramCard({discovery,status,onSave}:{discovery:DiscoveryDefinition;status:'new'|'saved'|'done';onSave:(id:DiscoveryId,value:'saved'|'done')=>void}){const reason=discovery.id==='familyRegistry'?'不動産と預貯金に関する情報があるため、複数の相続手続きで戸籍類を扱う可能性がある確認候補として表示しています。':'借金・保証債務について「あることを把握している」と回答したため、家庭裁判所の公式情報を確認する候補として表示しています。';return <section className="program-card"><div><p className="section-kicker">新しい確認候補が見つかりました</p><h2>{discovery.title}</h2><p>{discovery.description}</p><details className="discovery-reason"><summary>なぜ表示された？</summary><p>{reason}</p></details></div><div className="program-actions"><OfficialLink href={discovery.href}>公式情報を見る</OfficialLink><button className={status==='saved'?'is-saved':''} onClick={()=>onSave(discovery.id,'saved')}>{status==='saved'?'確認リストに追加済み':'確認リストに追加'}</button><button onClick={()=>onSave(discovery.id,'done')}>{status==='done'?'確認済み':'後で見る'}</button></div></section>}
function Timeline(){return <section className="timeline-card"><div className="section-kicker">見通しをつくる</div><h2>手続きタイムライン</h2><p className="timeline-note">一般的な手続きの目安です。起算日・要否は状況や制度によって異なります。</p><div className="journey-timeline"><TimeItem when="いま" title="初期確認・資料集め">遺言書、相続人候補、財産と債務の手がかりを整理します。</TimeItem><TimeItem when="原則3か月以内｜起算日は状況によって異なります" title={<OfficialLink href="https://www.courts.go.jp/saiban/syurui/syurui_kazi/kazi_06_13/index.html">相続放棄・限定承認の検討</OfficialLink>}>期間がある制度です。具体的な期限は家庭裁判所の公式案内で確認してください。</TimeItem><TimeItem when="一般的な目安｜4か月以内となる場合" title={<OfficialLink href="https://www.nta.go.jp/taxes/shiraberu/taxanswer/shotoku/2022.htm">準確定申告</OfficialLink>}>必要となる場合があります。要否や起算日は国税庁・税務署へ確認してください。</TimeItem><TimeItem when="一般的な目安｜10か月以内となる場合" title={<OfficialLink href="https://www.nta.go.jp/taxes/tetsuzuki/shinsei/shinkoku/sozoku/sozoku.htm">相続税の申告・納付</OfficialLink>}>必要となる場合があります。具体的な情報は国税庁の公式案内で確認してください。</TimeItem></div><p className="official-cta"><b>重要な制度は、公式情報を確認してください。</b> <OfficialLink href="https://www.courts.go.jp/">裁判所</OfficialLink>・<OfficialLink href="https://www.nta.go.jp/">国税庁</OfficialLink></p></section>}
function TimeItem({when,title,children}:{when:string;title:ReactNode;children:ReactNode}){return <div className="time-item"><i/><div><time>{when}</time><b>{title}</b><p>{children}</p></div></div>}
function OfficialLink({href,children}:{href:string;children:ReactNode}){return <a className="official-link" href={href} target="_blank" rel="noreferrer" title="国の機関による案内を新しいタブで開く">{children}<span aria-hidden="true">↗</span></a>}
